import csv,json,math,pathlib,hashlib,statistics
p=pathlib.Path(__file__).resolve().parent; f=p/'atlas_396_source.tsv';rows=list(csv.DictReader(f.open(),delimiter='\t'));assert len(rows)==396 and len({r['pair_id'] for r in rows})==396
ranked=sorted(rows,key=lambda r:float(r['global_rg_p']));q=1.;corrected={}
for i in range(395,-1,-1):q=min(q,float(ranked[i]['global_rg_p'])*396/(i+1));corrected[ranked[i]['pair_id']]=q
maxdiff=max(abs(corrected[r['pair_id']]-float(r['global_rg_fdr_all_396'])) for r in rows);assert maxdiff<1e-14
r=next(r for r in rows if r['pair_id']=='insomnia__adhd');native=json.loads((p/'fi_ffs_native_exact.json').read_text())[0];deletes=[float(x[0] if isinstance(x,list) else x) for x in native['delete_rg']];assert len(deletes)==200 and all(math.isfinite(x) for x in deletes);m=statistics.mean(deletes);se=math.sqrt(199/200*math.fsum((x-m)**2 for x in deletes));assert abs(se-native['rg_se'])<1e-12
result={'atlas_rows':396,'bh_max_abs_difference':maxdiff,'insomnia_adhd':{'rg_rounded':float(r['global_rg']),'se_rounded':float(r['global_rg_se']),'atlas_z_rounded':float(r['global_rg_z']),'atlas_p':float(r['global_rg_p']),'bh_q_recomputed':corrected[r['pair_id']],'p_rank':next(i+1 for i,x in enumerate(ranked) if x['pair_id']==r['pair_id']),'source_log_reference':r['ldsc_input_log'],'p_from_rounded_rg_divided_by_rounded_se':math.erfc(abs(float(r['global_rg'])/float(r['global_rg_se']))/math.sqrt(2))},'fi_ffs':{'n_snps':native['n_snps'],'rg':native['rg'],'se_reported':native['rg_se'],'se_recomputed_from_delete_rg':se,'delete_blocks':len(deletes),'p_underflow':native['p_underflow']},'hashes':{x.name:hashlib.sha256(x.read_bytes()).hexdigest() for x in [f,p/'fi_ffs_native_exact.json']}}
(p/'audit_receipt.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
